SourceCode.Declaration:
class TFMLogicComponentDataContext extends TFMLogicComponent implements TFMDataInputEnabledInterface
{
    TableName   inputData;
    Name        blockName;

}

Method.Source:
public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    if (!inputData)
    {
        refCon.addCollector(TFMGetReferenceData::defaultReferenceIdentity(10));
    }
    return refCon;
}

public TFMRegistrationCollectors registrationCollectors(TFMRequestElement _request = null)
{
    TFMRegistrationCollectors ret;


    return ret;
}

[TFMParameter('')]
public TableName parmInputData(TableName _inputData = inputData)
{
    inputData = _inputData;
    return inputData;
}

[TFMParameter('', "@TFM:Blocktogetdatafrom")]
public TFMLogicBlockName parmBlockName(TFMLogicBlockName _blockName = blockName)
{
    blockName = _blockName;
    return blockName;
}

/// <summary>
/// Method that tells which request Class it's data can be parsed into
/// </summary>
/// <returns>The name of the request class the components data can be parsed to</returns>
public ClassName requestClassProvided()
{
    return classStr(TFMRequestBasicElement);
}

public Common getData(TFMRequestElement _request)
{
    Common dataInContext = _request.logicContext().getDataContext(inputData, blockName);
    Common dataFromHeader = _request.getReferredRecord();

    return dataInContext != null ? dataInContext : dataFromHeader;
}
